-- Paket ABT "abt-pihak-urut-sisa-28okt" (28 Okt 2026): sisa variabel Derry dan bawaan ABT (izin pengguna) yang memilih pihak dengan `urutan = N` tetap menjadi PERINGKAT ke-N (perkara e-Court dengan urutan bersambung).
-- 120 baris variabel diubah (10, 11, 20, 21, 24, 27, 45, 99, 100, 103, 104, 118, 120, 335, 336, 337, 341, 342, 343, 345, 346, 347, 1033, 1034, 1035, 1076, 1077, 1173, 1174, 1176, 1517, 1518, 2173, 3111, 3112, 3113, 3114, 3115, 3116, 3117, 3118, 3121, 3122, 3123, 3124, 3125, 3126, 3127, 3128, 3131, 3642, 3643, 3673, 4440, 5019, 5027, 5028, 5078, 5079, 5080, 5081, 5083, 5084, 5085, 5086, 5087, 5088, 5091, 5092, 5093, 5094, 5095, 5096, 5099, 5102, 5103, 5104, 5106, 5107, 5116, 5842, 7000, 7003, 7004, 7078, 8129, 8175, 8179, 8180, 8510, 8524, 8533, 8800, 8801, 8802, 8803, 8808, 8809, 8810, 8811, 8890, 9104, 9200, 9205, 9277, 9278, 9279, 9280, 9281, 9290, 9291, 9292, 9293, 9404, 9405, 9560, 9561, 9562, 10106, 10107), 1 fungsi tersimpan baru (isian_rtf_pihak_peringkat). Prasyarat: paket abt-pihak-urut-ecourt-27okt sudah terpasang.
-- UJIVAR-BERAT: kueri berat (9280 9281 9290 9291), dijalankan pasang-satker.sh untuk SATU perkara contoh (@pid diisi skrip). Hanya memeriksa kueri berjalan tanpa galat.
SELECT 9280 AS no_var, COUNT(*) AS baris FROM (SELECT x.data FROM (SELECT IF(IFNULL((SELECT TRIM(CONVERT(t.data USING utf8)) FROM aps_badilag.abt_data_teks t WHERE t.no_var = 9282 AND t.perkara_id = @pid), '') <> '', IFNULL((SELECT TRIM(CONVERT(t.data USING utf8)) FROM aps_badilag.abt_data_teks t WHERE t.no_var = 9282 AND t.perkara_id = @pid), ''), (SELECT CONCAT('0 Nomor ', c.nomor_perkara, ' tanggal ', CONCAT(DAY(cp.tanggal_putusan), ' ', ELT(MONTH(cp.tanggal_putusan),'Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'), ' ', YEAR(cp.tanggal_putusan))) FROM perkara c JOIN perkara_pihak1 c1 ON c1.perkara_id = c.perkara_id AND NOT EXISTS (SELECT 1 FROM perkara_pihak1 zc1 WHERE zc1.perkara_id = c1.perkara_id AND (IFNULL(zc1.urutan, 0) < IFNULL(c1.urutan, 0) OR (IFNULL(zc1.urutan, 0) = IFNULL(c1.urutan, 0) AND zc1.id < c1.id))) JOIN perkara_pihak2 c2 ON c2.perkara_id = c.perkara_id AND NOT EXISTS (SELECT 1 FROM perkara_pihak2 zc2 WHERE zc2.perkara_id = c2.perkara_id AND (IFNULL(zc2.urutan, 0) < IFNULL(c2.urutan, 0) OR (IFNULL(zc2.urutan, 0) = IFNULL(c2.urutan, 0) AND zc2.id < c2.id))) JOIN pihak a1 ON a1.id = c1.pihak_id JOIN pihak a2 ON a2.id = c2.pihak_id JOIN perkara_putusan cp ON cp.perkara_id = c.perkara_id LEFT JOIN perkara_akta_cerai ac ON ac.perkara_id = c.perkara_id JOIN perkara h JOIN perkara_pihak1 h1 JOIN perkara_pihak2 h2 JOIN pihak b1 JOIN pihak b2 WHERE h.perkara_id = @pid AND h1.perkara_id = h.perkara_id AND NOT EXISTS (SELECT 1 FROM perkara_pihak1 zh1 WHERE zh1.perkara_id = h1.perkara_id AND (IFNULL(zh1.urutan, 0) < IFNULL(h1.urutan, 0) OR (IFNULL(zh1.urutan, 0) = IFNULL(h1.urutan, 0) AND zh1.id < h1.id))) AND h2.perkara_id = h.perkara_id AND NOT EXISTS (SELECT 1 FROM perkara_pihak2 zh2 WHERE zh2.perkara_id = h2.perkara_id AND (IFNULL(zh2.urutan, 0) < IFNULL(h2.urutan, 0) OR (IFNULL(zh2.urutan, 0) = IFNULL(h2.urutan, 0) AND zh2.id < h2.id))) AND b1.id = h1.pihak_id AND b2.id = h2.pihak_id AND c.jenis_perkara_id IN (346, 347) AND c.perkara_id <> h.perkara_id AND c.tanggal_pendaftaran <= h.tanggal_pendaftaran AND cp.tanggal_putusan IS NOT NULL AND ((((IFNULL(a1.nomor_indentitas,'') = IFNULL(b1.nomor_indentitas,'-') AND LENGTH(b1.nomor_indentitas) >= 10) OR REPLACE(REPLACE(REPLACE(REPLACE(TRIM(SUBSTRING_INDEX(SUBSTRING_INDEX(LOWER(a1.nama), ' bin', 1), ' als', 1)), ' ', ''), '.', ''), ',', ''), CHAR(39), '') = REPLACE(REPLACE(REPLACE(REPLACE(TRIM(SUBSTRING_INDEX(SUBSTRING_INDEX(LOWER(b1.nama), ' bin', 1), ' als', 1)), ' ', ''), '.', ''), ',', ''), CHAR(39), '')) AND ((IFNULL(a2.nomor_indentitas,'') = IFNULL(b2.nomor_indentitas,'-') AND LENGTH(b2.nomor_indentitas) >= 10) OR REPLACE(REPLACE(REPLACE(REPLACE(TRIM(SUBSTRING_INDEX(SUBSTRING_INDEX(LOWER(a2.nama), ' bin', 1), ' als', 1)), ' ', ''), '.', ''), ',', ''), CHAR(39), '') = REPLACE(REPLACE(REPLACE(REPLACE(TRIM(SUBSTRING_INDEX(SUBSTRING_INDEX(LOWER(b2.nama), ' bin', 1), ' als', 1)), ' ', ''), '.', ''), ',', ''), CHAR(39), ''))) OR (((IFNULL(a1.nomor_indentitas,'') = IFNULL(b2.nomor_indentitas,'-') AND LENGTH(b2.nomor_indentitas) >= 10) OR REPLACE(REPLACE(REPLACE(REPLACE(TRIM(SUBSTRING_INDEX(SUBSTRING_INDEX(LOWER(a1.nama), ' bin', 1), ' als', 1)), ' ', ''), '.', ''), ',', ''), CHAR(39), '') = REPLACE(REPLACE(REPLACE(REPLACE(TRIM(SUBSTRING_INDEX(SUBSTRING_INDEX(LOWER(b2.nama), ' bin', 1), ' als', 1)), ' ', ''), '.', ''), ',', ''), CHAR(39), '')) AND ((IFNULL(a2.nomor_indentitas,'') = IFNULL(b1.nomor_indentitas,'-') AND LENGTH(b1.nomor_indentitas) >= 10) OR REPLACE(REPLACE(REPLACE(REPLACE(TRIM(SUBSTRING_INDEX(SUBSTRING_INDEX(LOWER(a2.nama), ' bin', 1), ' als', 1)), ' ', ''), '.', ''), ',', ''), CHAR(39), '') = REPLACE(REPLACE(REPLACE(REPLACE(TRIM(SUBSTRING_INDEX(SUBSTRING_INDEX(LOWER(b1.nama), ' bin', 1), ' als', 1)), ' ', ''), '.', ''), ',', ''), CHAR(39), '')))) ORDER BY (ac.nomor_akta_cerai IS NOT NULL) DESC, cp.tanggal_putusan DESC LIMIT 1)) AS data) x WHERE IFNULL(x.data, '') <> '') AS uji_9280;
SELECT 9281 AS no_var, COUNT(*) AS baris FROM (SELECT x.data FROM (SELECT IF(IFNULL((SELECT TRIM(CONVERT(t.data USING utf8)) FROM aps_badilag.abt_data_teks t WHERE t.no_var = 1321 AND t.perkara_id = @pid), '') <> '', CONCAT(IFNULL((SELECT TRIM(CONVERT(t.data USING utf8)) FROM aps_badilag.abt_data_teks t WHERE t.no_var = 1321 AND t.perkara_id = @pid), ''), IFNULL(CONCAT(' tanggal ', CONCAT(DAY((SELECT t.data FROM aps_badilag.abt_data_tanggal t WHERE t.no_var = 1322 AND t.perkara_id = @pid AND t.data IS NOT NULL LIMIT 1)), ' ', ELT(MONTH((SELECT t.data FROM aps_badilag.abt_data_tanggal t WHERE t.no_var = 1322 AND t.perkara_id = @pid AND t.data IS NOT NULL LIMIT 1)),'Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'), ' ', YEAR((SELECT t.data FROM aps_badilag.abt_data_tanggal t WHERE t.no_var = 1322 AND t.perkara_id = @pid AND t.data IS NOT NULL LIMIT 1)))), '')), (SELECT CONCAT(ac.nomor_akta_cerai, IFNULL(CONCAT(' tanggal ', CONCAT(DAY(ac.tgl_akta_cerai), ' ', ELT(MONTH(ac.tgl_akta_cerai),'Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'), ' ', YEAR(ac.tgl_akta_cerai))), '')) FROM perkara c JOIN perkara_pihak1 c1 ON c1.perkara_id = c.perkara_id AND NOT EXISTS (SELECT 1 FROM perkara_pihak1 zc1 WHERE zc1.perkara_id = c1.perkara_id AND (IFNULL(zc1.urutan, 0) < IFNULL(c1.urutan, 0) OR (IFNULL(zc1.urutan, 0) = IFNULL(c1.urutan, 0) AND zc1.id < c1.id))) JOIN perkara_pihak2 c2 ON c2.perkara_id = c.perkara_id AND NOT EXISTS (SELECT 1 FROM perkara_pihak2 zc2 WHERE zc2.perkara_id = c2.perkara_id AND (IFNULL(zc2.urutan, 0) < IFNULL(c2.urutan, 0) OR (IFNULL(zc2.urutan, 0) = IFNULL(c2.urutan, 0) AND zc2.id < c2.id))) JOIN pihak a1 ON a1.id = c1.pihak_id JOIN pihak a2 ON a2.id = c2.pihak_id JOIN perkara_putusan cp ON cp.perkara_id = c.perkara_id LEFT JOIN perkara_akta_cerai ac ON ac.perkara_id = c.perkara_id JOIN perkara h JOIN perkara_pihak1 h1 JOIN perkara_pihak2 h2 JOIN pihak b1 JOIN pihak b2 WHERE h.perkara_id = @pid AND h1.perkara_id = h.perkara_id AND NOT EXISTS (SELECT 1 FROM perkara_pihak1 zh1 WHERE zh1.perkara_id = h1.perkara_id AND (IFNULL(zh1.urutan, 0) < IFNULL(h1.urutan, 0) OR (IFNULL(zh1.urutan, 0) = IFNULL(h1.urutan, 0) AND zh1.id < h1.id))) AND h2.perkara_id = h.perkara_id AND NOT EXISTS (SELECT 1 FROM perkara_pihak2 zh2 WHERE zh2.perkara_id = h2.perkara_id AND (IFNULL(zh2.urutan, 0) < IFNULL(h2.urutan, 0) OR (IFNULL(zh2.urutan, 0) = IFNULL(h2.urutan, 0) AND zh2.id < h2.id))) AND b1.id = h1.pihak_id AND b2.id = h2.pihak_id AND c.jenis_perkara_id IN (346, 347) AND c.perkara_id <> h.perkara_id AND c.tanggal_pendaftaran <= h.tanggal_pendaftaran AND cp.tanggal_putusan IS NOT NULL AND ((((IFNULL(a1.nomor_indentitas,'') = IFNULL(b1.nomor_indentitas,'-') AND LENGTH(b1.nomor_indentitas) >= 10) OR REPLACE(REPLACE(REPLACE(REPLACE(TRIM(SUBSTRING_INDEX(SUBSTRING_INDEX(LOWER(a1.nama), ' bin', 1), ' als', 1)), ' ', ''), '.', ''), ',', ''), CHAR(39), '') = REPLACE(REPLACE(REPLACE(REPLACE(TRIM(SUBSTRING_INDEX(SUBSTRING_INDEX(LOWER(b1.nama), ' bin', 1), ' als', 1)), ' ', ''), '.', ''), ',', ''), CHAR(39), '')) AND ((IFNULL(a2.nomor_indentitas,'') = IFNULL(b2.nomor_indentitas,'-') AND LENGTH(b2.nomor_indentitas) >= 10) OR REPLACE(REPLACE(REPLACE(REPLACE(TRIM(SUBSTRING_INDEX(SUBSTRING_INDEX(LOWER(a2.nama), ' bin', 1), ' als', 1)), ' ', ''), '.', ''), ',', ''), CHAR(39), '') = REPLACE(REPLACE(REPLACE(REPLACE(TRIM(SUBSTRING_INDEX(SUBSTRING_INDEX(LOWER(b2.nama), ' bin', 1), ' als', 1)), ' ', ''), '.', ''), ',', ''), CHAR(39), ''))) OR (((IFNULL(a1.nomor_indentitas,'') = IFNULL(b2.nomor_indentitas,'-') AND LENGTH(b2.nomor_indentitas) >= 10) OR REPLACE(REPLACE(REPLACE(REPLACE(TRIM(SUBSTRING_INDEX(SUBSTRING_INDEX(LOWER(a1.nama), ' bin', 1), ' als', 1)), ' ', ''), '.', ''), ',', ''), CHAR(39), '') = REPLACE(REPLACE(REPLACE(REPLACE(TRIM(SUBSTRING_INDEX(SUBSTRING_INDEX(LOWER(b2.nama), ' bin', 1), ' als', 1)), ' ', ''), '.', ''), ',', ''), CHAR(39), '')) AND ((IFNULL(a2.nomor_indentitas,'') = IFNULL(b1.nomor_indentitas,'-') AND LENGTH(b1.nomor_indentitas) >= 10) OR REPLACE(REPLACE(REPLACE(REPLACE(TRIM(SUBSTRING_INDEX(SUBSTRING_INDEX(LOWER(a2.nama), ' bin', 1), ' als', 1)), ' ', ''), '.', ''), ',', ''), CHAR(39), '') = REPLACE(REPLACE(REPLACE(REPLACE(TRIM(SUBSTRING_INDEX(SUBSTRING_INDEX(LOWER(b1.nama), ' bin', 1), ' als', 1)), ' ', ''), '.', ''), ',', ''), CHAR(39), '')))) ORDER BY (ac.nomor_akta_cerai IS NOT NULL) DESC, cp.tanggal_putusan DESC LIMIT 1)) AS data) x WHERE IFNULL(x.data, '') <> '') AS uji_9281;
SELECT 9290 AS no_var, COUNT(*) AS baris FROM (SELECT y.data FROM (SELECT IF(v.ga IS NOT NULL, IF(LOCATE(',', v.ga) = 0, v.ga, NULL), IF(v.gb IS NOT NULL AND LOCATE(',', v.gb) = 0, v.gb, NULL)) AS data FROM (SELECT u.*, IF(u.ga IS NULL, (SELECT GROUP_CONCAT(DISTINCT k.post_code ORDER BY k.post_code) FROM kode_pos k WHERE k.subdistrict LIKE CONCAT(u.c_2, '%') COLLATE utf8mb4_unicode_ci AND REPLACE(REPLACE(REPLACE(SUBSTRING_INDEX(k.subdistrict, '(', 1), ' ', ''), '-', ''), '.', '') COLLATE utf8mb4_general_ci = u.c_n AND REPLACE(REPLACE(REPLACE(SUBSTRING_INDEX(IF(k.district LIKE 'Kabupaten %', SUBSTRING(k.district, 11), IF(k.district LIKE 'Kota %', SUBSTRING(k.district, 6), k.district)), '(', 1), ' ', ''), '-', ''), '.', '') COLLATE utf8mb4_general_ci = u.d_n AND REPLACE(REPLACE(REPLACE(SUBSTRING_INDEX(k.province, '(', 1), ' ', ''), '-', ''), '.', '') COLLATE utf8mb4_general_ci = u.p_n), NULL) AS gb FROM (SELECT n.*, (SELECT GROUP_CONCAT(DISTINCT k.post_code ORDER BY k.post_code) FROM kode_pos k WHERE k.subdistrict LIKE CONCAT(n.c_2, '%') COLLATE utf8mb4_unicode_ci AND REPLACE(REPLACE(REPLACE(SUBSTRING_INDEX(k.subdistrict, '(', 1), ' ', ''), '-', ''), '.', '') COLLATE utf8mb4_general_ci = n.c_n AND REPLACE(REPLACE(REPLACE(SUBSTRING_INDEX(IF(k.district LIKE 'Kabupaten %', SUBSTRING(k.district, 11), IF(k.district LIKE 'Kota %', SUBSTRING(k.district, 6), k.district)), '(', 1), ' ', ''), '-', ''), '.', '') COLLATE utf8mb4_general_ci = n.d_n AND REPLACE(REPLACE(REPLACE(SUBSTRING_INDEX(k.province, '(', 1), ' ', ''), '-', ''), '.', '') COLLATE utf8mb4_general_ci = n.p_n AND REPLACE(REPLACE(REPLACE(SUBSTRING_INDEX(k.area, '(', 1), ' ', ''), '-', ''), '.', '') COLLATE utf8mb4_general_ci = n.a_n) AS ga FROM (SELECT REPLACE(REPLACE(REPLACE(SUBSTRING_INDEX(kl.kelurahan_nama, '(', 1), ' ', ''), '-', ''), '.', '') AS a_n, LEFT(kc.kecamatan_nama, 2) AS c_2, REPLACE(REPLACE(REPLACE(SUBSTRING_INDEX(kc.kecamatan_nama, '(', 1), ' ', ''), '-', ''), '.', '') AS c_n, REPLACE(REPLACE(REPLACE(SUBSTRING_INDEX(IF(kb.kabupaten_nama LIKE 'Kabupaten %', SUBSTRING(kb.kabupaten_nama, 11), IF(kb.kabupaten_nama LIKE 'Kota %', SUBSTRING(kb.kabupaten_nama, 6), kb.kabupaten_nama)), '(', 1), ' ', ''), '-', ''), '.', '') AS d_n, REPLACE(REPLACE(REPLACE(SUBSTRING_INDEX(pv.provinsi_nama, '(', 1), ' ', ''), '-', ''), '.', '') AS p_n FROM perkara_pihak1 p JOIN pihak b ON b.id = p.pihak_id JOIN ref_kelurahan_new kl ON kl.kelurahan_kode = TRIM(b.kelurahan) JOIN ref_kecamatan_new kc ON kc.kecamatan_kode = kl.kecamatan_kode JOIN ref_kabupaten_new kb ON kb.kabupaten_kode = LEFT(kl.kecamatan_kode, 5) JOIN ref_provinsi_new pv ON pv.provinsi_kode = LEFT(kl.kecamatan_kode, 2) WHERE p.perkara_id = @pid AND aps_badilag.isian_rtf_pihak_peringkat(1, p.id) = 1 AND NOT (p.alamat LIKE '%tidak diketahui%' OR p.alamat LIKE 'Dahulu%') LIMIT 1) n) u) v) y WHERE y.data IS NOT NULL) AS uji_9290;
SELECT 9291 AS no_var, COUNT(*) AS baris FROM (SELECT y.data FROM (SELECT IF(v.ga IS NOT NULL, IF(LOCATE(',', v.ga) = 0, v.ga, NULL), IF(v.gb IS NOT NULL AND LOCATE(',', v.gb) = 0, v.gb, NULL)) AS data FROM (SELECT u.*, IF(u.ga IS NULL, (SELECT GROUP_CONCAT(DISTINCT k.post_code ORDER BY k.post_code) FROM kode_pos k WHERE k.subdistrict LIKE CONCAT(u.c_2, '%') COLLATE utf8mb4_unicode_ci AND REPLACE(REPLACE(REPLACE(SUBSTRING_INDEX(k.subdistrict, '(', 1), ' ', ''), '-', ''), '.', '') COLLATE utf8mb4_general_ci = u.c_n AND REPLACE(REPLACE(REPLACE(SUBSTRING_INDEX(IF(k.district LIKE 'Kabupaten %', SUBSTRING(k.district, 11), IF(k.district LIKE 'Kota %', SUBSTRING(k.district, 6), k.district)), '(', 1), ' ', ''), '-', ''), '.', '') COLLATE utf8mb4_general_ci = u.d_n AND REPLACE(REPLACE(REPLACE(SUBSTRING_INDEX(k.province, '(', 1), ' ', ''), '-', ''), '.', '') COLLATE utf8mb4_general_ci = u.p_n), NULL) AS gb FROM (SELECT n.*, (SELECT GROUP_CONCAT(DISTINCT k.post_code ORDER BY k.post_code) FROM kode_pos k WHERE k.subdistrict LIKE CONCAT(n.c_2, '%') COLLATE utf8mb4_unicode_ci AND REPLACE(REPLACE(REPLACE(SUBSTRING_INDEX(k.subdistrict, '(', 1), ' ', ''), '-', ''), '.', '') COLLATE utf8mb4_general_ci = n.c_n AND REPLACE(REPLACE(REPLACE(SUBSTRING_INDEX(IF(k.district LIKE 'Kabupaten %', SUBSTRING(k.district, 11), IF(k.district LIKE 'Kota %', SUBSTRING(k.district, 6), k.district)), '(', 1), ' ', ''), '-', ''), '.', '') COLLATE utf8mb4_general_ci = n.d_n AND REPLACE(REPLACE(REPLACE(SUBSTRING_INDEX(k.province, '(', 1), ' ', ''), '-', ''), '.', '') COLLATE utf8mb4_general_ci = n.p_n AND REPLACE(REPLACE(REPLACE(SUBSTRING_INDEX(k.area, '(', 1), ' ', ''), '-', ''), '.', '') COLLATE utf8mb4_general_ci = n.a_n) AS ga FROM (SELECT REPLACE(REPLACE(REPLACE(SUBSTRING_INDEX(kl.kelurahan_nama, '(', 1), ' ', ''), '-', ''), '.', '') AS a_n, LEFT(kc.kecamatan_nama, 2) AS c_2, REPLACE(REPLACE(REPLACE(SUBSTRING_INDEX(kc.kecamatan_nama, '(', 1), ' ', ''), '-', ''), '.', '') AS c_n, REPLACE(REPLACE(REPLACE(SUBSTRING_INDEX(IF(kb.kabupaten_nama LIKE 'Kabupaten %', SUBSTRING(kb.kabupaten_nama, 11), IF(kb.kabupaten_nama LIKE 'Kota %', SUBSTRING(kb.kabupaten_nama, 6), kb.kabupaten_nama)), '(', 1), ' ', ''), '-', ''), '.', '') AS d_n, REPLACE(REPLACE(REPLACE(SUBSTRING_INDEX(pv.provinsi_nama, '(', 1), ' ', ''), '-', ''), '.', '') AS p_n FROM perkara_pihak2 p JOIN pihak b ON b.id = p.pihak_id JOIN ref_kelurahan_new kl ON kl.kelurahan_kode = TRIM(b.kelurahan) JOIN ref_kecamatan_new kc ON kc.kecamatan_kode = kl.kecamatan_kode JOIN ref_kabupaten_new kb ON kb.kabupaten_kode = LEFT(kl.kecamatan_kode, 5) JOIN ref_provinsi_new pv ON pv.provinsi_kode = LEFT(kl.kecamatan_kode, 2) WHERE p.perkara_id = @pid AND aps_badilag.isian_rtf_pihak_peringkat(2, p.id) = 1 AND NOT (p.alamat LIKE '%tidak diketahui%' OR p.alamat LIKE 'Dahulu%') AND p.ghaib = 0 LIMIT 1) n) u) v) y WHERE y.data IS NOT NULL) AS uji_9291;
